import {analyze} from './detector.mjs?v=20261114-4';
import {CASE_BANK,drawRound,scoreAnswer} from './cases.mjs?v=20261114-4';
const $=s=>document.querySelector(s);
const node=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
const evidence=(id,title,quote,why)=>({id,title,quotes:[quote],why});
const usedCases=new Set();
let cases=drawRound(usedCases);
let aiGeneration=0;
let liveRoom=null, liveState=null, pollHandle=null, liveOffset=0, liveBusy=false;
let timed=false,deadline=0,frozenRemaining=20000,points=0,awarded=new Map();
let current=0, mode='training', pinned=new Map(),answers=new Map(),revealed=false,customText='';
const list=$('#case-list');
function updateList(){list.replaceChildren();cases.forEach((c,i)=>{const b=node('button','','case-row'+(mode==='training'&&i===current?' active':'')+(answers.has(i)?' solved':''));b.setAttribute('aria-label',`Case ${i+1}: ${c.title}${answers.has(i)?', reviewed':''}`);if(mode==='training'&&i===current)b.setAttribute('aria-current','true');const text=node('span');text.append(node('span',c.title,'case-row-title'),node('span',c.subtitle,'case-row-subtitle'),node('span',answers.has(i)?'FILE REVIEWED':'CASE FILE / '+String(i+1).padStart(3,'0'),'case-row-tag'));b.append(node('span',String(i+1).padStart(2,'0'),'case-num'),text,node('span','','row-dot'));b.addEventListener('click',()=>{if(!liveRoom&&!timed)openCase(i);});if(liveRoom||timed)b.disabled=true;list.append(b);});$('#case-counter').textContent=`${answers.size} / ${cases.length} FILED`;const correct=[...answers.values()].filter(Boolean).length;$('#detective-rank').textContent=answers.size===cases.length?(correct===cases.length?'Chief of trust issues':correct>=3?'Sharp-eyed investigator':'Detective in training'):'Unlicensed detective';$('#detective-score').textContent=answers.size?`${correct} correct · ${answers.size} file${answers.size===1?'':'s'} reviewed`:'80 cases. Ten fresh rounds.';}
function setPanel(panel){$('.workspace').dataset.mobilePanel=panel;document.querySelectorAll('[data-panel]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===panel);b.setAttribute('aria-pressed',String(b.dataset.panel===panel));});$('#notebook').classList.remove('show-notebook');if(matchMedia('(max-width:650px)').matches)window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPanel(b.dataset.panel)));
$('#notes-toggle').addEventListener('click',()=>{if(matchMedia('(max-width:650px)').matches)setPanel('notebook');else $('#notebook').classList.toggle('show-notebook');});
$('#notes-close').addEventListener('click',()=>$('#notebook').classList.remove('show-notebook'));
function noteArticle(clue,i){const item=node('article','','clue-note');const heading=node('div','','clue-note-heading');heading.append(node('span',String(i+1).padStart(2,'0')),node('h3',clue.title));item.append(heading,node('q',clue.quotes.join(' · ')),node('p',clue.why));return item;}
function renderNotes(all){const container=$('#notes-body');container.replaceChildren();const clues=all||[...pinned.values()];$('#clue-count').textContent=`${pinned.size} clue${pinned.size===1?'':'s'} pinned`;$('#notes-count').textContent=clues.length;if(!clues.length){if(revealed){container.append(node('p','No obvious warning patterns were found. That does not establish that the message is genuine. Verify the sender and context independently.','notes-intro'));}else{const intro=node('p','','notes-intro');intro.append(node('b','Your gut has entered the chat.'),document.createTextNode(' Tap underlined phrases in the message to pin your evidence here.'));const empty=node('div','','notes-empty');empty.append(node('span','⌕','doodle-search'),node('p','No clues pinned. Yet.\nGood detectives look twice.'));container.append(intro,empty);}}else{container.append(node('p',revealed?'THE EVIDENCE, UNPACKED':`${clues.length} OBSERVATION${clues.length===1?'':'S'} PINNED`,'notes-summary'));clues.forEach((clue,i)=>container.append(noteArticle(clue,i)));}}
function makeEvidence(part,index){const b=node('button',part.text,'evidence-word');b.dataset.clue=String(index);b.setAttribute('aria-pressed',String(pinned.has(index)));b.classList.toggle('selected',pinned.has(index));b.classList.toggle('revealed',revealed);b.setAttribute('aria-label',`Investigate: ${part.text}`);b.addEventListener('click',()=>{if(revealed)return;if(pinned.has(index))pinned.delete(index);else pinned.set(index,part.clue);b.classList.toggle('selected',pinned.has(index));b.setAttribute('aria-pressed',String(pinned.has(index)));renderNotes();});return b;}
function renderMessage(){const container=$('#message-content');container.replaceChildren();container.classList.toggle('own-case-message',mode==='lab');if(mode==='lab'){highlightCustom(customText,analyze(customText).findings);return;}cases[current].parts.forEach((part,i)=>container.append(typeof part==='string'?document.createTextNode(part):makeEvidence(part,i)));}
function resetDesk(){$('.desk-disclaimer').textContent='A second opinion, never proof. This tool cannot verify a sender or certify a message as safe.';pinned=new Map();revealed=false;$('#case-outcome').hidden=true;$('#case-outcome').replaceChildren();$('#next-case').hidden=true;$('#verdict-buttons').hidden=false;$('#desk').classList.remove('lab-mode');$('.desk-status').replaceChildren(node('span','● WORKING LOCALLY'),node('span','NO UPLOADED OR SAVED MESSAGES'),node('span','KL / 2026'));$('#case-status').classList.remove('closed');$('#case-status').replaceChildren(node('i'),document.createTextNode(' OPEN CASE'));$('#document-hint').textContent='↑ Tap anything that makes you suspicious.';}
function openCase(index){deadline=timed?Date.now()+20000:0;frozenRemaining=20000;current=index;mode='training';resetDesk();const c=cases[index];$('#case-category').textContent=c.category;$('#case-title').textContent=c.title;$('#crumb').textContent='Case files';$('#crumb-id').textContent=String(index+1).padStart(3,'0');$('#channel-label').textContent=c.channel;$('#sender-name').textContent=c.sender;$('#sender-detail').textContent=c.detail;$('#sender-avatar').textContent=c.avatar;renderMessage();renderNotes();updateList();setPanel('desk');if(answers.has(index))showOutcome(answers.get(index),false);}
function caseClues(){return cases[current].parts.filter(p=>typeof p!=='string').map(p=>p.clue);}
function showOutcome(correct,record=true){revealed=true;if(record){frozenRemaining=Math.max(0,deadline-Date.now());answers.set(current,correct);const earned=scoreAnswer(correct,timed?Math.max(0,deadline-Date.now()):0);awarded.set(current,earned);points+=earned;updateHUD();}$('#verdict-buttons').hidden=true;$('#case-status').classList.add('closed');$('#case-status').replaceChildren(node('i'),document.createTextNode(' FILE REVIEWED'));$('#document-hint').textContent='Evidence unpacked. Open your case notes for the details.';renderMessage();renderNotes(caseClues());const outcome=$('#case-outcome');outcome.replaceChildren(node('span',correct?'INSTINCTS: SHARP':'LESSON: LEARNED','outcome-stamp'),node('h3',correct?'You’re getting hard to fool.':'One for your detective notebook.'),node('p',cases[current].explanation));outcome.hidden=false;$('#next-case').hidden=false;$('#next-case').replaceChildren(document.createTextNode(answers.size===cases.length?'All files reviewed · Start again':'Open the next case'),node('span',answers.size===cases.length?'↺':'→'));updateList();if(correct&&record)celebrate();}
document.querySelectorAll('[data-verdict]').forEach(b=>b.addEventListener('click',()=>{if(revealed||mode!=='training')return;showOutcome((b.dataset.verdict==='true')===cases[current].suspicious);}));
$('#next-case').addEventListener('click',()=>{if(answers.size===cases.length){newRound();}else{let next=cases.findIndex((_,i)=>i>current&&!answers.has(i));if(next<0)next=cases.findIndex((_,i)=>!answers.has(i));openCase(next);}});
$('#reset').addEventListener('click',()=>newRound());
const dialogs=['compose','guide','help','about','privacy','faq','live'];for(const id of dialogs){const button=$('#'+(id==='compose'?'compose':id+'-open'));button.addEventListener('click',()=>$('#'+id+'-dialog').showModal());}
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#custom-message').addEventListener('input',()=>{$('#char-count').textContent=`${$('#custom-message').value.length} / 2000`;$('#custom-message').setCustomValidity('');});
function highlightCustom(text,findings){const root=$('#message-content');root.replaceChildren();const ranges=[];findings.forEach(f=>f.quotes.forEach(quote=>{let from=0;const lower=text.toLowerCase(),needle=quote.toLowerCase();while(needle&&from<text.length){const start=lower.indexOf(needle,from);if(start<0)break;ranges.push({start,end:start+quote.length,clue:f});from=start+quote.length;}}));ranges.sort((a,b)=>a.start-b.start||b.end-a.end);let at=0;for(const range of ranges){if(range.start<at)continue;root.append(document.createTextNode(text.slice(at,range.start)));const mark=node('mark',text.slice(range.start,range.end),'evidence-word revealed');root.append(mark);at=range.end;}root.append(document.createTextNode(text.slice(at)));}
function runLocalCheck(event){aiGeneration++;event.preventDefault();const input=$('#custom-message');if(!input.value.trim()){input.setCustomValidity('Add a message to investigate.');input.reportValidity();return;}if(liveRoom)leaveRoom();customText=input.value;mode='lab';resetDesk();mode='lab';revealed=true;$('#desk').classList.add('lab-mode');$('#compose-dialog').close();$('#case-category').textContent='PRIVATE INVESTIGATION / YOUR MESSAGE';$('#case-title').textContent='Let’s read between the lines.';$('#crumb').textContent='Message lab';$('#crumb-id').textContent='LOCAL';$('#channel-label').textContent='YOUR MESSAGE';$('#sender-name').textContent='Unverified sender';$('#sender-detail').textContent='Pasted by you · Processed on this device';$('#sender-avatar').textContent='⌕';$('#document-hint').textContent='Highlighted phrases matched common warning patterns.';const result=analyze(customText);renderMessage();renderNotes(result.findings);$('#case-status').replaceChildren(node('i'),document.createTextNode(' PATTERN CHECK'));$('#verdict-buttons').hidden=true;const out=$('#case-outcome');out.replaceChildren(node('span',`${result.findings.length} WARNING PATTERN${result.findings.length===1?'':'S'}`,'outcome-stamp'),node('h3',result.level),node('p',result.findings.length?'Pause before you act. Do not reply, pay, share codes, or follow message links. Check through the company’s known app or website; for personal messages, use a contact you already know.':'We did not find a matching warning pattern. This is not verification. Check the sender and context independently before sharing anything or acting.'));const again=node('button','Check another message ↗','scan-again');again.addEventListener('click',()=>$('#compose-dialog').showModal());out.append(again);out.hidden=false;updateList();setPanel('desk');}

function celebrate(){if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const party=node('div','','confetti');party.setAttribute('aria-hidden','true');for(let i=0;i<22;i++){const bit=node('i');bit.style.setProperty('--x',`${Math.random()*100}vw`);bit.style.setProperty('--r',`${Math.random()*720}deg`);bit.style.setProperty('--delay',`${Math.random()*.3}s`);bit.style.background=['#c94627','#d7ef74','#b6a1c8','#f3d78f'][i%4];party.append(bit);}document.body.append(party);setTimeout(()=>party.remove(),2000);}
openCase(0);

function newRound(){aiGeneration++;if(liveRoom){leaveRoom();}cases=drawRound(usedCases);answers.clear();awarded.clear();points=0;openCase(0);updateHUD();}
function updateHUD(){const hud=$('#round-hud');hud.hidden=mode==='lab';$('#points-value').textContent=String(points);$('#mode-label').textContent=timed?'BEAT THE CLOCK':'PRACTICE ROUND';const remaining=deadline?Math.max(0,Math.ceil((revealed?frozenRemaining:deadline-Date.now())/1000)):0;$('#timer-value').textContent=timed?`${remaining}s`:'∞';hud.classList.toggle('timer-urgent',timed&&remaining<=5&&!revealed);$('#timer-caption').textContent=timed?'LEFT THIS CASE':'TAKE YOUR TIME';}
$('#sprint-open').addEventListener('click',()=>$('#sprint-dialog').showModal());
$('#sprint-start').addEventListener('click',()=>{timed=true;$('#sprint-dialog').close();newRound();});
$('#practice-mode').addEventListener('click',()=>{timed=false;newRound();});
setInterval(()=>{if(liveRoom)return;if(timed&&mode==='training'&&!revealed&&deadline&&Date.now()>=deadline){showOutcome(false);$('#case-outcome h3').textContent='Time’s up. A clue for next time.';}updateHUD();},250);
updateHUD();

const ROOM_API='https://phish-bureau-live.narutoxkillua.chatgpt.site';
let lastLiveView='',lastLiveAnswer='',lastLiveBoard='',answerBusy=false;
async function roomRequest(path,body,credential){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),path==='/analyze'?30000:10000);try{const response=await fetch(ROOM_API+path,{method:'POST',headers:{'Content-Type':'application/json',...(credential?{Authorization:'Bearer '+credential}:{})},body:JSON.stringify(body),signal:controller.signal});let data;try{data=await response.json();}catch{throw Error('Room service is not available. Solo modes still work.');}if(!response.ok)throw Error(data.error||'The room request failed.');return data;}catch(error){if(error.name==='AbortError')throw Error('Room connection timed out. Try again.');throw error;}finally{clearTimeout(timeout);}}
function persistRoom(){try{if(liveRoom)sessionStorage.setItem('phish-room',JSON.stringify(liveRoom));else sessionStorage.removeItem('phish-room');}catch{}}
function leaveRoom(){if(pollHandle)clearInterval(pollHandle);pollHandle=null;liveRoom=null;liveState=null;liveBusy=false;lastLiveView='';lastLiveAnswer='';lastLiveBoard='';persistRoom();$('#desk').classList.remove('live-mode');$('.notebook-heading h2').textContent='The little things matter.';$('#live-status-error')?.remove();}
function startPolling(){if(pollHandle)clearInterval(pollHandle);pollRoom();pollHandle=setInterval(pollRoom,2000);}
async function pollRoom(){if(!liveRoom||liveBusy||answerBusy)return;liveBusy=true;const activeRoom=liveRoom;try{const state=await roomRequest('/state',{code:activeRoom.code},activeRoom.playerToken);if(liveRoom!==activeRoom||answerBusy)return;liveOffset=state.serverNow-Date.now();liveState=state;renderLive(state);$('#live-status-error')?.remove();}catch(error){if(liveRoom!==activeRoom)return;let notice=$('#live-status-error');if(!notice){notice=node('p','','live-error');notice.id='live-status-error';$('#notes-body').prepend(notice);}notice.textContent=error.message+' Reconnecting…';}finally{liveBusy=false;}}
function renderLeaderboard(state){const signature=JSON.stringify([state.status,state.players]);if(signature===lastLiveBoard)return;lastLiveBoard=signature;const root=$('#notes-body');root.replaceChildren();root.append(node('p',state.status==='finished'?'FINAL STANDINGS':'LIVE STANDINGS · UPDATES EVERY 2s','notes-summary'));const table=node('table','','leaderboard');const caption=node('caption','Players ranked by points, then correct calls.');caption.className='sr-only';table.append(caption);const head=node('thead'),tr=node('tr');['#','DETECTIVE','PTS'].forEach(t=>tr.append(node('th',t)));head.append(tr);table.append(head);const body=node('tbody');let rank=0,previous=null;state.players.forEach((p,i)=>{if(!previous||p.score!==previous.score||p.correct!==previous.correct)rank=i+1;previous=p;const row=node('tr','',''+(p.id===state.playerId?'is-me':''));row.append(node('td',String(rank)),node('td',p.name+(p.id===state.playerId?' (you)':'')),node('td',String(p.score)));body.append(row);});table.append(body);root.append(table,node('p','100 per correct call + up to 40 for speed. Missed cases score zero. Tied scores share a rank.','room-session-label'));if(liveRoom.hostToken&&state.status==='lobby'){const start=node('button','Start for everyone ↗','flag-button');start.style.marginTop='20px';start.addEventListener('click',async()=>{start.disabled=true;try{await roomRequest('/start',{code:liveRoom.code},liveRoom.hostToken);await pollRoom();}catch(e){start.disabled=false;root.append(node('p',e.message,'live-error'));}});root.append(start);}const controls=node('div','','room-controls');const copy=node('button','Copy invite ↗');copy.addEventListener('click',async()=>{const url=new URL(location.href);url.searchParams.set('room',liveRoom.code);try{await navigator.clipboard.writeText(url.toString());copy.textContent='Invite copied ✓';}catch{copy.textContent='Room code: '+liveRoom.code;}});const exit=node('button','Leave room');exit.addEventListener('click',()=>{leaveRoom();timed=false;newRound();});controls.append(copy,exit);root.append(controls);}
function renderLive(state){$('.desk-status').replaceChildren(node('span','● LIVE ROOM CONNECTED'),node('span','NICKNAMES + SCORES SHARED'),node('span','KL / 2026'));mode='live';timed=false;$('#desk').classList.add('live-mode');$('#round-hud').hidden=false;$('.notebook-heading h2').textContent=state.status==='finished'?'The final word.':'The leaderboard.';$('#crumb').textContent='Live room';$('#crumb-id').textContent=state.code;$('#mode-label').textContent='ROOM '+state.code;const me=state.players.find(p=>p.id===state.playerId);$('#points-value').textContent=String(me?.score||0);$('#case-counter').textContent=`${state.players.length} / 24 PLAYERS`;$('#detective-rank').textContent=state.status==='finished'?'Round complete':'Live investigation';$('#detective-score').textContent=state.code+' · '+state.players.length+' players';$('#notes-count').textContent=state.players.length;
 list.replaceChildren();state.players.forEach((p,i)=>{const row=node('div','','case-row'+(p.id===state.playerId?' active':''));const text=node('span');text.append(node('span',p.name,'case-row-title'),node('span',`${p.correct} correct · ${p.answered} answered`,'case-row-subtitle'));row.append(node('span',String(i+1).padStart(2,'0'),'case-num'),text,node('span',String(p.score),'case-row-tag'));list.append(row);});renderLeaderboard(state);
 const view=state.status+':'+state.index;if(view!==lastLiveView){lastLiveView=view;lastLiveAnswer='';resetDesk();$('#desk').classList.add('live-mode');$('#round-hud').hidden=false;$('#next-case').hidden=true;$('#case-category').textContent='LIVE ROOM / '+state.code;$('#case-status').replaceChildren(node('i'),document.createTextNode(state.status==='playing'?' LIVE CASE':state.status==='finished'?' FINISHED':' WAITING'));$('#document-hint').textContent='Same case. Same clock. Trust your judgment.';if(state.question){cases=[state.question];current=0;$('#case-title').textContent=state.question.title;$('#sender-name').textContent=state.question.sender;$('#sender-detail').textContent=state.question.detail;$('#sender-avatar').textContent=state.question.avatar;$('#channel-label').textContent=state.question.channel;$('#message-content').replaceChildren(document.createTextNode(state.question.parts.join('')));$('#verdict-buttons').hidden=false;}else{$('#verdict-buttons').hidden=true;$('#case-title').textContent=state.status==='finished'?'The results are in.':'Your rivals are assembling.';$('#sender-name').textContent='The Phish Bureau';$('#sender-detail').textContent='Shared investigation room';$('#sender-avatar').textContent='✳';$('#channel-label').textContent='COMPETITION DESK';const text=state.status==='finished'?'Round complete. Open the notebook for the final leaderboard. Create a new room for a fresh set of cases.':state.status==='countdown'?'Get ready. Eight messages. Twenty seconds each. The first case opens together.':'Room '+state.code+' is open. Share the code with your friends. Everyone must join before the host starts.';$('#message-content').replaceChildren(node('div',text,'lobby-message'));if(state.status==='lobby')$('#message-content').append(node('span',state.code,'room-code-display'));}setPanel('desk');$('.desk-status').replaceChildren(node('span','● LIVE ROOM CONNECTED'),node('span','NICKNAMES + SCORES SHARED'),node('span','KL / 2026'));}
 if(state.answer){const key=state.index+':'+state.answer.points;if(key!==lastLiveAnswer){lastLiveAnswer=key;revealed=true;$('#verdict-buttons').hidden=true;const out=$('#case-outcome');out.replaceChildren(node('span',`+${state.answer.points} POINTS`,'outcome-stamp'),node('h3',state.answer.correct?'Good call. Stay sharp.':'A lesson for the next case.'),node('p',state.answer.explanation));out.hidden=false;}}
 updateLiveClock();}
function updateLiveClock(){if(!liveRoom||!liveState)return;const state=liveState,now=Date.now()+liveOffset;const remaining=state.status==='playing'?Math.max(0,state.deadline-now):state.status==='countdown'?Math.max(0,state.startAt-now):0;$('#timer-value').textContent=state.status==='lobby'?'—':state.status==='finished'?'✓':Math.ceil(remaining/1000)+'s';$('#timer-caption').textContent=state.status==='lobby'?'WAITING':state.status==='countdown'?'STARTING IN':state.status==='finished'?'ROUND OVER':'LEFT THIS CASE';$('#round-hud').classList.toggle('timer-urgent',state.status==='playing'&&remaining<=5000&&!state.answer);if(state.status==='playing'&&remaining<=0){$('#verdict-buttons').hidden=true;$('#document-hint').textContent='Case closed. Synchronizing the next case…';}}
setInterval(updateLiveClock,200);
document.querySelectorAll('[data-verdict]').forEach(b=>b.addEventListener('click',async()=>{if(!liveRoom||!liveState||liveState.status!=='playing'||liveState.answer||answerBusy)return;answerBusy=true;const room=liveRoom;const index=liveState.index;document.querySelectorAll('[data-verdict]').forEach(x=>x.disabled=true);try{const result=await roomRequest('/answer',{code:room.code,index,choice:b.dataset.verdict==='true'},room.playerToken);if(liveRoom===room){liveState.answer=result;renderLive(liveState);if(result.correct)celebrate();await pollRoom();}}catch(error){if(liveRoom===room){$('#case-outcome').replaceChildren(node('p',error.message,'live-error'));$('#case-outcome').hidden=false;await pollRoom();}}finally{answerBusy=false;document.querySelectorAll('[data-verdict]').forEach(x=>x.disabled=false);}}));
$('#room-form').addEventListener('submit',async event=>{event.preventDefault();const name=$('#player-name').value.trim(),code=$('#room-code').value.trim().toUpperCase();const connect=$('#room-connect');connect.disabled=true;$('#room-error').textContent='Connecting…';try{const result=await roomRequest(code?'/join':'/rooms',{name,...(code?{code}:{used:[...usedCases]})});leaveRoom();liveRoom=result;(result.caseIds||[]).forEach(id=>usedCases.add(id));persistRoom();lastLiveView='';$('#live-dialog').close();$('#room-error').textContent='';startPolling();}catch(error){$('#room-error').textContent=error.message;}finally{connect.disabled=false;}});
