if(['#privacy','#faq'].includes(location.hash))$('#'+location.hash.slice(1)+'-dialog').showModal();

$('#compose-form').addEventListener('submit',async event=>{event.preventDefault();$('#ai-form-error').textContent='';if(event.submitter?.dataset.check==='local'){runLocalCheck(event);return;}const input=$('#custom-message');const text=input.value.trim();if(!text)return;if(!$('#ai-consent').checked){$('#ai-form-error').textContent='Select the checkbox to send this text to Google, or choose the local check.';return;}if(liveRoom)leaveRoom();const request=++aiGeneration;customText=text;mode='lab';resetDesk();mode='lab';revealed=true;$('#desk').classList.add('lab-mode');$('#compose-dialog').close();$('#case-category').textContent='GEMMA 4 / AI MESSAGE REVIEW';$('#case-title').textContent='A second opinion is on the case.';$('#crumb').textContent='AI message lab';$('#crumb-id').textContent='GEMMA 4';$('#sender-name').textContent='Your submitted message';$('#sender-detail').textContent='Sent to Google for AI review · Not saved by this app';$('#sender-avatar').textContent='✳';$('#channel-label').textContent='MESSAGE EVIDENCE';$('#message-content').replaceChildren(document.createTextNode(text));$('#document-hint').textContent='AI reviews text only. Links are never opened.';$('#verdict-buttons').hidden=true;$('#next-case').hidden=true;$('#notes-body').replaceChildren(node('p','Gemma 4 is examining the message…','notes-intro'));$('#case-outcome').hidden=false;$('#case-outcome').replaceChildren(node('h3','Gemma 4 is reviewing…'),node('p','Looking for warning signs, context, and a safe next step.'));$('.desk-status').replaceChildren(node('span','● GEMMA 4 AI REVIEW'),node('span','MESSAGE SENT TO GOOGLE'));setPanel('desk');try{const result=await roomRequest('/analyze',{message:text,consent:true});if(request!==aiGeneration||mode!=='lab'||customText!==text)return;const labels={likely_scam:'Likely scam — pause before acting',uncertain:'Uncertain — verify independently',no_obvious_signs:'No obvious scam signs — still verify'};const out=$('#case-outcome');out.replaceChildren(node('span','GEMMA 4 · AI ASSESSMENT','outcome-stamp'),node('h3',labels[result.verdict]||'Review the evidence'),node('p',result.summary));out.append(node('p','AI can be wrong. This does not verify identity, links, or safety.','limit'));$('#notes-body').replaceChildren(node('p','GEMMA 4’S OBSERVATIONS','notes-summary'));result.clues.forEach((c,i)=>$('#notes-body').append(noteArticle({title:'Clue '+(i+1),quotes:[c.quote],why:c.reason},i)));const steps=node('div','','ai-next-steps');steps.append(node('h3','Your safer next move'));result.nextSteps.forEach(s=>steps.append(node('p','→ '+s)));$('#notes-body').append(steps);$('#notes-count').textContent=result.clues.length;$('#case-status').replaceChildren(node('i'),document.createTextNode(' AI REVIEWED'));}catch(error){if(request!==aiGeneration||mode!=='lab')return;$('#case-outcome').replaceChildren(node('h3','AI review unavailable'),node('p',error.message));const retry=node('button','Try again or check locally ↗','scan-again');retry.addEventListener('click',()=>$('#compose-dialog').showModal());$('#case-outcome').append(retry);$('#notes-body').replaceChildren(node('p','No AI assessment was returned. You can still run the separate local pattern check.','notes-intro'));}});
$('#email-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;const note=$('#import-note');try{if(file.size>65536)throw Error('Choose a file smaller than 64 KB.');if(!/\.(eml|txt)$/i.test(file.name))throw Error('Choose an .eml or .txt file.');const raw=await file.text();const {importEmail}=await import('./email-import.mjs?v=20261114-4');const extracted=/\.eml$/i.test(file.name)?importEmail(raw):raw;$('#custom-message').value=extracted.slice(0,2000);$('#custom-message').dispatchEvent(new Event('input'));$('#ai-consent').checked=false;note.textContent=extracted.length>2000?'Imported the first 2000 characters. Review and remove private details before sending.':'Imported locally. Review the text and remove private details before sending.';}catch(error){note.textContent=error.message;}event.target.value='';});
